def max_sub_array(nums):
    def go(lo, hi):
        if lo == hi: return nums[lo]
        mid = (lo + hi) // 2
        left = go(lo, mid); right = go(mid+1, hi)
        suf = acc = nums[mid]
        for i in range(mid-1, lo-1, -1):
